function UIBattlingPickCard:Init()
    self:InitListener()
    self:InitComponent()
end

function UIBattlingPickCard:InitComponent()
    if IsNull(self.skillCard) then return end
    local skillData = self.skillCard.skillCardData
    local skillId = skillData.skillId
    local star = skillData.star
    local posData = { self.skillCard.curTransArrLinePos, self.skillCard.curTransArrLine }
    local skillCardVo = UIBattlingTools.GetSkillCardInfoByTwoParam(skillId, star) -- 技能卡配表数据
    local listSkillCardIds = skillCardVo.cardBehaviorParam
    if isNull(listSkillCardIds) or #listSkillCardIds <= 0 then return end
    self:InitPickCardList(listSkillCardIds, star, posData)
end

function UIBattlingPickCard:InitListener()
     UIEventProxy.Create(self.Btn_ClosePanel.gameObject).onPointerClick = function()
        
         self.runCloseAction = true
         UIModule.CloseDialog(self.controller)
     end
end

function UIBattlingPickCard:RemoveListener()
end

function UIBattlingPickCard:CleanListSkillCard()
end

function UIBattlingPickCard:InitPickCardList(cardList, star, posData)
    if self.listSkillCard2Choose then self.listSkillCard2Choose = {} end
    local skillList = {}
    local roleId = self.skillCard.skillCardRoleId
    for i, skillIndex in pairs(cardList) do
        local skillId = UIBattlingDataMgr:GetRoleDataByRoleId(roleId).skillList[checkString(skillIndex)].skillId
        table.insert(skillList, skillId)
    end
    for i, skillCardId in pairs(skillList) do
        if Tools.isNullKey(skillCardId) then
            goto continue
        end
        local go = KTool.Instantiate(self.CardList.gameObject, self.SkillCardCell.gameObject)
        if not IsNull(go) then
            local lbSkillCard = KTool.GetComponent(go, typeof(LuaBehaviour))
            if not IsNull(lbSkillCard) then
                lbSkillCard:Init()
                local ltSkillCard = lbSkillCard.Env
                if ltSkillCard then
                    ltSkillCard:SetSkillCardInfo(checkInt(skillCardId), star, posData, cardList[i])
                    table.insert(self.listSkillCard2Choose, ltSkillCard)
                    ltSkillCard:SetCallBack(function()
                        UIModule.CloseDialog(self.controller)
                    end)
                    KTool.SetActive(ltSkillCard.controller.gameObject, true)
                end
            end
        end
        :: continue ::
    end
end
